/**
 * A clean HEAD alone is ordinary project state. When there is no formal task to settle, the ordinary
 * admission is the repository outcome: the retired plan's declared artifacts, or a direct commit in
 * a task-free project. A recorded current conclusion takes precedence over re-deriving that prompt.
 */
async function deliveryGuidance(
  deps: WorkRuntimeDeps,
  status: ReturnType<WorkRuntimeDeps["controller"]["status"]>,
  requested: string | null,
): Promise<{ reasons: string[]; next: string[] } | null> {
  const { controller, deliveryPulse } = deps;
  const direct = status.directOutcome;
  const head = direct?.repositoryHead;
  const repository = controller.effects.git.repository;
  if (
    deliveryPulse === undefined || repository === undefined || !head ||
    (direct.relation !== "IN_SYNC" && direct.relation !== "DIRECT_AHEAD") ||
    status.attempts.some((attempt) => attempt.orphaned === true)
  ) return null;

  const plannedIds = new Set(controller.work.project().tasks.map((task) => task.task_id));
  const retired = status.tasks.filter((task) => task.state === "STALE" && !plannedIds.has(task.task_id));
  const noFormalTasks = status.tasks.length === 0 && plannedIds.size === 0;
  if (
    (retired.length === 0 && !noFormalTasks) ||
    (requested !== null && !retired.some((task) => task.task_id === requested))
  ) return null;

  let artifacts: string[] = [];
  let reason: string;
  if (retired.length > 0) {
    const declared = new Set<string>();
    for (const task of retired) {
      const envelope = controller.taskEnvelopeOrNull(task.task_id);
      if (envelope === null) return null;
      for (const path of envelope.required_artifacts) declared.add(path);
    }
    if (declared.size === 0) return null;
    artifacts = [...declared];
    reason = `the retired plan's declared artifacts (${artifacts.join(", ")}) are committed at repository HEAD ${head}`;
  } else {
    reason =
      direct.relation === "DIRECT_AHEAD"
        ? `a direct commit exists at repository HEAD ${head} ahead of the canonical head ${direct.projectHead.slice(0, 12)}; it is a repository outcome, not a governed result and this readiness does not accept it`
        : `the repository and the canonical head agree at ${head}; the existing outcome is in the basis, not a new governed delta`;
  }

  const pulse = await deliveryPulse.pulse().catch(() => null);
  if (
    pulse === null || pulse.basis.projectRevision !== status.revision || pulse.basis.headCommit !== status.headCommit ||
    pulse.episode.readiness.deliveryBlockers.length > 0 || pulse.episode.readiness.failedOrBlockedTasks.length > 0 ||
    pulse.execution.jobs.some((job) => job.phase === "QUEUED" || job.phase === "RUNNING")
  ) return null;

  // Re-observe Git after the asynchronous episode read. An unobservable worktree cannot prove a clean basis.
  const basis = observeCanonicalBasis(repository);
  if (basis?.head !== head || basis.uncommittedPaths?.length !== 0) return null;
  const git = gitTextRunner(repository);

  const conclusion = pulse.episode.current ? pulse.episode.conclusion : null;
  if (conclusion !== null) {
    return {
      reasons: [reason, `this episode has a current recorded ${conclusion.intent} conclusion`],
      next: ["reply using the recorded conclusion"],
    };
  }

  if (retired.length > 0) {
    try {
      if (!artifacts.every((path) => statSync(join(repository, path), { throwIfNoEntry: false })?.isFile() === true &&
        git(["cat-file", "-t", `${head}:${path}`])?.trim() === "blob")) return null;
    } catch {
      return null;
    }
    return {
      reasons: [reason, "the episode has no mechanical delivery blockers; decide whether the committed artifacts satisfy the user's goal"],
      next: ["if the committed artifacts satisfy the goal, call palimpsest_work action=conclude intent=DELIVER with your statement and the artifact paths"],
    };
  }

  // A task-free project has no declared artifacts. The changed blobs in the direct commit are the
  // only committed paths this entry can name; an unchanged or uncommitted project has no delivery.
  if (direct.relation !== "DIRECT_AHEAD") return null;
  const changed = git(["diff", "--name-only", "--no-renames", direct.projectHead, head]);
  if (changed === null) return null;
  const committedPaths = changed
    .split(/\r?\n/u)
    .map((path) => path.trim())
    .filter((path) => path !== "" && git(["cat-file", "-t", `${head}:${path}`])?.trim() === "blob");
  if (committedPaths.length === 0) return null;
  return {
    reasons: [
      `a direct commit at repository HEAD ${head} changes ${committedPaths.join(", ")}; it is a repository outcome, not a governed result and this readiness does not accept it`,
      "the project has no formal task and no uncommitted work; decide whether the committed change satisfies the user's goal",
    ],
    next: [
      `if the committed change satisfies the goal, call palimpsest_work action=conclude intent=DELIVER with your statement and the artifact paths (${committedPaths.join(", ")})`,
    ],
  };
}

